#!/usr/bin/env bash
# ============================================================================
# VideoMind Redesign - Part 2: Landing page + /library split
# ============================================================================
# Option 2: / becomes a pure landing page; the video library moves to /library.
#
#   Replaces : frontend/src/app/page.tsx           (landing, no longer fetches)
#   Creates  : frontend/src/app/library/page.tsx   (library, logic lifted intact)
#   Edits    : frontend/src/components/layout/Navbar.tsx (Library -> /library)
#
# Touches NO lib/, hooks, upload, wallet, or API code. Presentation + routing only.
# Requires Part 1 (VM_PART1_FOUNDATION) to be applied first.
#
#   ./vm_part2_landing.sh          apply
#   ./vm_part2_landing.sh --revert restore all three from backups
#
# Run from the repo root (the dir containing frontend/).
# ============================================================================
set -euo pipefail

MARKER_FILE="frontend/src/app/library/page.tsx"
GLOBALS="frontend/src/app/globals.css"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR="frontend/.vm_part2_backups"

L="frontend/src/app/page.tsx"
LIB="frontend/src/app/library/page.tsx"
NAV="frontend/src/components/layout/Navbar.tsx"

say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }

[ -f "$L" ] || die "$L not found. Run from the repo root (folder containing frontend/)."

# ---- revert -----------------------------------------------------------------
if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir ($BAKDIR). Nothing to revert."
  LATEST="$(ls -1d $BAKDIR/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found in $BAKDIR."
  cp "$LATEST/page.tsx"   "$L"
  cp "$LATEST/Navbar.tsx" "$NAV"
  rm -f "$LIB"
  # remove /library dir if now empty
  rmdir "frontend/src/app/library" 2>/dev/null || true
  say "Reverted page.tsx + Navbar.tsx from $LATEST"
  say "Removed $LIB"
  exit 0
fi

# ---- guards -----------------------------------------------------------------
grep -q "VM_PART1_FOUNDATION" "$GLOBALS" 2>/dev/null || die "Part 1 not applied. Run ./vm_part1_foundation.sh first."

if [ -f "$MARKER_FILE" ] && grep -q "export default function Library" "$MARKER_FILE" 2>/dev/null; then
  say "Part 2 already applied ($MARKER_FILE exists). Use --revert to undo."
  exit 0
fi

# ---- backup ----------------------------------------------------------------
mkdir -p "$BAKDIR/$STAMP"
cp "$L"   "$BAKDIR/$STAMP/page.tsx"
cp "$NAV" "$BAKDIR/$STAMP/Navbar.tsx"
say "Backups saved to $BAKDIR/$STAMP/"

# ---- decode + verify each payload BEFORE writing ---------------------------
decode() { # $1=b64var $2=expected-substring $3=label -> echoes tmp path
  local tmp; tmp="$(mktemp)"
  printf '%s' "$1" | base64 -d > "$tmp" || die "$3: base64 decode failed."
  grep -q "$2" "$tmp" || die "$3: decoded payload failed verification (missing '$2'). Nothing written."
  printf '%s' "$tmp"
}

T_LANDING="$(decode "" "actionable" "landing page")"
T_LIBRARY="$(decode "" "export default function Library" "library page")"
T_NAVBAR="$(decode "" "/library" "navbar")"

# ---- write ------------------------------------------------------------------
mkdir -p "frontend/src/app/library"
cp "$T_LANDING" "$L"
cp "$T_LIBRARY" "$LIB"
cp "$T_NAVBAR"  "$NAV"
rm -f "$T_LANDING" "$T_LIBRARY" "$T_NAVBAR"

# ---- post-write verify ------------------------------------------------------
grep -q "actionable" "$L" || die "landing write verify failed - restore from $BAKDIR/$STAMP"
grep -q "export default function Library" "$LIB" || die "library write verify failed."
grep -q '"/library"' "$NAV" || die "navbar write verify failed."

say "Applied Part 2:"
say "  / is now the landing page"
say "  /library holds your video library"
say "  Navbar Library link -> /library"
say "Next: cd frontend && npm run build   (verify locally before deploying)"
